using FinancialManager.Domain.Accounts;
using FinancialManager.Domain.Common;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace FinancialManager.Infrastructure.Persistence.Configurations;

internal sealed class TransactionConfiguration : IEntityTypeConfiguration<Transaction>
{
    public void Configure(EntityTypeBuilder<Transaction> builder)
    {
        builder.ToTable("Transactions");
        builder.HasKey(t => t.Id);

        // Keys are generated by the domain, so EF must treat unseen keys as new rows.
        builder.Property(t => t.Id).ValueGeneratedNever();

        builder.Property(t => t.Amount).HasPrecision(DomainLimits.MoneyPrecision, DomainLimits.MoneyScale);
        builder.Property(t => t.Description).HasMaxLength(DomainLimits.TransactionDescriptionMaxLength).IsRequired();
        builder.Property(t => t.Type).IsRequired();

        builder.HasIndex(t => new { t.AccountId, t.Date });
    }
}
